INSERT INTO pages (slug,title,body) VALUES ('about','About Sutoloka','<p><strong>Sutoloka (সুতোলোকা)</strong> means “the world of thread”. We are a Bangladeshi fashion label for the whole family, designing comfortable, colourful clothing that fits the way we live — from everyday kurtis and polos to festive sarees and panjabis.</p><h3>What we stand for</h3><ul><li>Fabrics chosen for our climate: breathable, soft and easy to care for.</li><li>Fair prices with clear sizing, so you get the right fit the first time.</li><li>Cash on delivery across all 64 districts and a simple 7-day exchange.</li></ul><p>Thank you for choosing Sutoloka.</p>');
INSERT INTO pages (slug,title,body) VALUES ('shipping-policy','Shipping & Delivery','<h3>Delivery charges</h3><ul><li>Inside Dhaka city: ৳70 (1–2 days)</li><li>Dhaka sub-areas (Savar, Keraniganj, Gazipur, Narayanganj): ৳100 (2–3 days)</li><li>Outside Dhaka: ৳130 (2–4 days)</li><li>Free delivery on orders over ৳3,000.</li></ul><p>We call to confirm every order before shipping. You pay in cash when the parcel arrives.</p>');
INSERT INTO pages (slug,title,body) VALUES ('return-and-exchange','Return & Exchange','<p>Not the right size or colour? You can exchange within <strong>7 days</strong> of delivery.</p><ul><li>Items must be unused, unwashed and have tags attached.</li><li>Message us with your order number and a photo of the item.</li><li>Inside Dhaka we can pick up from your door; outside Dhaka please send it by courier.</li><li>If an item arrives damaged or wrong, we replace it free of charge.</li></ul><p>Refunds for unavailable exchanges are sent by bKash or Nagad within 3 working days.</p>');
INSERT INTO pages (slug,title,body) VALUES ('privacy-policy','Privacy Policy','<p>We collect only what we need to deliver your order: your name, phone number, address and order details.</p><ul><li>We never sell or share your information with third parties, except the courier that delivers your parcel.</li><li>Your phone number is used for order updates and, if you sign in, for one-time login codes.</li><li>You can ask us to delete your account and data at any time.</li></ul>');
INSERT INTO pages (slug,title,body) VALUES ('terms-and-conditions','Terms & Conditions','<ul><li>Prices are in Bangladeshi Taka (৳) and include VAT where applicable.</li><li>Colours may vary slightly due to screen settings and photography lighting.</li><li>We may cancel orders that cannot be confirmed by phone, or that show signs of misuse.</li><li>Coupons and offers cannot be combined unless stated.</li><li>Reward points have no cash value and expire 12 months after they are earned.</li></ul>');
